      inset: calc((var(--ui-control-sm) - var(--ui-control-md)) / 2) 0;
    }
  }

  .button[data-size="lg"] {
    height: var(--ui-control-lg);
    min-width: var(--ui-control-lg);
    padding-inline: var(--ui-space-5);
    font-size: var(--ui-text-md);
  }

  /* Hover and press mix from --button-bg and --button-fg, so overrides get
     matching shades. Filled or not, every button sits on the one control
     shadow: no glint along the top, nothing darker under the bottom edge. */
  .button[data-variant="primary"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-ink);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 92%, var(--button-fg));
    --button-bg-press: color-mix(in oklch, var(--button-bg) 85%, var(--button-fg));
    --button-fg: var(--ui-on-ink);
  }

  .button[data-variant="secondary"] {
    --button-bg: var(--ui-surface);
    --button-edge: var(--ui-border-strong);
    --button-depth: var(--ui-shadow-control);
  }

  .button[data-variant="danger"] {
    --button-depth: var(--ui-shadow-control);
    --button-bg: var(--ui-danger);
    --button-bg-hover: color-mix(in oklch, var(--button-bg) 93%, black);
    --button-bg-press: color-mix(in oklch, var(--button-bg) 86%, black);
    --button-fg: var(--ui-on-danger);
  }

  @media (hover: hover) {
    .button:hover:not(:disabled, [aria-busy])::before {
      background: var(--button-bg-hover);
    }
    .button[data-variant="secondary"]:hover:not(:disabled, [aria-busy])::before {
      background: var(--ui-fill-solid);
    }
  }

  .button:active:not(:disabled, [aria-busy])::before {
    --button-depth: 0 0 transparent;
    background: var(--button-bg-press);
    transition-duration: var(--ui-dur-press);
  }

  .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
    scale: var(--ui-scale-press);
  }

  .button:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .button:disabled {
    opacity: 0.5;
    cursor: default;
  }

  .button[aria-busy] {
    cursor: default;
  }

  .content {
    display: inline-flex;
    align-items: center;
    gap: var(--ui-space-2);
    /* Room for descenders inside the busy mask, cancelled by the negative margin.
       Always on, so turning busy on never moves the label. */
    margin: -4px -6px;
    padding: var(--ui-space-1) 6px;
  }

  .content svg {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex-shrink: 0;
    pointer-events: none;
  }

  /* Shown only once the work has lasted 300ms (use-delayed-busy.ts), so the
     shimmer starts at once when it does. */
  .button[data-busy-shown] .content {
    --button-dim: 1;
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--button-dim)) 35%,
      black 50%,
      rgb(0 0 0 / var(--button-dim)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation:
      button-dim var(--ui-dur-base) var(--ui-ease-color) forwards,
      button-sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes button-dim {
    to {
      --button-dim: 0.4;
    }
  }

  @keyframes button-sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .button::before {
      transition-property: background-color, box-shadow;
    }
    .button:active:not(:disabled, [aria-busy], [aria-haspopup])::before {
      scale: none;
    }
    .button[data-busy-shown] .content {
      --button-dim: 0.5;
      animation: none;
    }
  }

  /* block: the full width of its container, label still centered. */
  .button[data-block] {
    display: grid;
    width: 100%;
  }
}

"use client";

import { isValidElement, type ComponentProps, type MouseEvent, type ReactNode } from "react";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./button.module.css";
import { useDelayedBusy } from "./use-delayed-busy";

type ButtonProps = ComponentProps<"button"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Work is in flight: presses are ignored at once, focus stays. The shimmer
   *  (and `busyLabel`) shows only once it has lasted 300ms, then for 400ms at least. */
  busy?: boolean;
  /** The label while the busy state shows, like "Saving…". Morphs from the label. */
  busyLabel?: ReactNode;
  /** Fills its container's width: the main action of a narrow form or a sheet. */
  block?: boolean;
};

export function Button({
  variant = "primary",
  size = "md",
  busy = false,
  busyLabel,
  block = false,
  type = "button",
  className,
  children,
  onClick,
  ...props
}: ButtonProps) {
  const shown = useDelayedBusy(busy);
  // One element and no text, named by aria-label: an icon button, drawn as a capsule.
  const iconOnly = isValidElement(children) && Boolean(props["aria-label"]);
  const label = shown && busyLabel !== undefined ? busyLabel : children;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    // Busy is not disabled: the button keeps focus and its tab stop.
    if (busy) {
      event.preventDefault();
      return;
    }
    onClick?.(event);
  }

  return (
    <button
      type={type}
      data-variant={variant}
      data-size={size}
      data-block={block || undefined}
      aria-busy={busy || undefined}
      aria-disabled={busy || undefined}
      data-busy-shown={shown || undefined}
      data-icon-only={iconOnly || undefined}
      className={className ? `${styles.button} ${className}` : styles.button}
      onClick={handleClick}
      {...props}
    >
      <span className={styles.content}>
        {typeof label === "string" ? <TextMorph>{label}</TextMorph> : label}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Whether to show that work is running. Fast work never shows: the busy
 * state appears only once `busy` has lasted `delay` ms, and once it has
 * appeared it stays at least `minimum` ms, so it never flickers in and out.
 */
export function useDelayedBusy(busy: boolean, delay = 300, minimum = 400) {
  const [shown, setShown] = useState(false);
  const since = useRef(0);

  useEffect(() => {
    if (busy === shown) return;
    const wait = busy ? delay : Math.max(0, minimum - (performance.now() - since.current));
    const timer = window.setTimeout(() => {
      if (busy) since.current = performance.now();
      setShown(busy);
    }, wait);
    return () => window.clearTimeout(timer);
  }, [busy, shown, delay, minimum]);

  return shown;
}

@layer theme, base, components, utilities;

/* Registered so the edge color and its mix toward danger transition separately. */
@property --code-edge {
  syntax: "<color>";
  inherits: false;
  initial-value: transparent;
}

/* The drawn caret's ink, registered so it can blink. */
@property --code-caret {
  syntax: "<color>";
  inherits: false;
  initial-value: transparent;
}

@property --code-danger {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .root {
    display: grid;
    /* The parent's width, never the boxes', so the row can shrink into it. */
    grid-template-columns: minmax(0, 1fr);
    justify-items: start;
    min-width: 0;
    gap: var(--ui-space-2);
    font-family: var(--ui-font-sans);
  }

  /* Focused only while it's a pill, so focus has somewhere to stay; the pill shows the state. */
  .root:focus {
    outline: none;
  }

  .label {
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  /* The boxes and the pill share one cell; the boxes stay in flow, so the row
     keeps its size whatever the pill does. */
  .stage {
    position: relative;
    display: grid;
    /* A column the stage's width, not the boxes' widest: the stage is as wide
       as the boxes when there's room and the boxes narrow when there isn't. */
    grid-template-columns: minmax(0, 1fr);
    max-width: 100%;
  }

  .boxes {
    --code-box-width: 44px;
    --code-box-min: 24px;
    --code-gap: var(--ui-space-2);
    --code-group-gap: var(--ui-space-5);
    --code-dot: 4px;
    display: flex;
    align-items: center;
    max-width: 100%;
    gap: var(--code-gap);
  }

  /* Between groups: a dot in a wider gap, so 123 · 456 reads the way it's said. */
  .separator {
    flex: none;
    width: var(--code-dot);
    height: var(--code-dot);
    margin-inline: calc((var(--code-group-gap) - 2 * var(--code-gap) - var(--code-dot)) / 2);
    border-radius: var(--ui-radius-full);
    background: var(--ui-muted);
    opacity: 0.6;
    transition: opacity var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  .root[data-phase="verifying"] .separator,
  .root[data-phase="success"] .separator {
    opacity: 0;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-exit);
  }

  .root[data-disabled] .separator {
    opacity: 0.3;
  }

  .box {
    --code-edge: var(--ui-border-strong);
    --code-edge-width: var(--ui-hairline);
    flex: 0 1 var(--code-box-width);
    box-sizing: border-box;
    width: var(--code-box-width);
    min-width: var(--code-box-min);
    height: var(--ui-control-lg);
    padding: 0;
    border: 0;
    border-radius: var(--ui-radius-md);
    background-color: var(--ui-surface);
    /* The caret is drawn, not the platform's: 2px, centered, the digit's height. */
    background-image: linear-gradient(var(--code-caret), var(--code-caret));
    background-position: center;
    background-repeat: no-repeat;
    background-size: 2px calc(1em - 2px);
    box-shadow: inset 0 0 0 var(--code-edge-width) color-mix(in oklch, var(--code-edge), var(--ui-danger) var(--code-danger));
    color: var(--ui-foreground);
    caret-color: transparent;
    /* Must stay over 16px, below which iOS zooms the page into a field. */
    font-family: var(--ui-font-sans);
    font-size: 24px;
    font-weight: var(--ui-weight-semibold);
    font-variant-numeric: tabular-nums;
    letter-spacing: 0;
    line-height: 1;
    text-align: center;
    outline: none;
    /* Opacity, drift and blur: the boxes coming back out of the pill. */
    transition:
      --code-edge var(--ui-dur-instant) var(--ui-ease-color),
      --code-danger var(--ui-dur-fast) var(--ui-ease-color),
      opacity var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      translate var(--ui-dur-glide) var(--ui-ease-glide),
      filter var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  .box::selection {
    background: var(--ui-selection);
  }

  .box[data-filled] {
    /* Only the text moves, by padding inside the fixed height; the box never resizes. */
    animation: code-char var(--ui-dur-fast) var(--ui-ease-enter);
  }

  @keyframes code-char {
    from {
      padding-top: 4px;
      color: transparent;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .box[data-filled] {
      animation: none;
    }
  }

  @media (hover: hover) {
    .box:hover:not(:focus, :disabled) {
      --code-edge: var(--ui-field-focus);
    }
  }

  /* The active box: its edge darkens at once and, while it's empty, a caret blinks in it. */
  .box:focus {
    --code-edge: var(--ui-field-focus);
    transition:
      --code-edge 0s,
      --code-danger var(--ui-dur-fast) var(--ui-ease-color),
      opacity var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      translate var(--ui-dur-glide) var(--ui-ease-glide),
      filter var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2);
  }

  .box:focus:not([data-filled]) {
    --code-caret: var(--ui-foreground);
    animation: code-caret calc(var(--ui-dur-pulse) * 2) steps(1, end) infinite;
  }

  @keyframes code-caret {
    50% { --code-caret: transparent; }
  }

  @media (prefers-reduced-motion: reduce) {
    .box:focus:not([data-filled]) {
      animation: none;
    }
  }

  .root[data-invalid] .box {
    --code-danger: 100%;
  }

  .box:disabled {
    opacity: 0.5;
    cursor: default;
    transition: none;
  }

  /* Set --code-message-lines when a longer error can arrive, so it never pushes the page. */
  .message {
    display: grid;
    min-height: calc(var(--code-message-lines, 1) * var(--ui-leading-md));
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  /* The error comes in from the field above it: a 2px drop with a blur clearing. */
  .error[data-shown] {
    animation: code-error-in var(--ui-dur-base) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2) backwards;
  }

  @keyframes code-error-in {
    from {
      translate: 0 -2px;
      filter: blur(2px);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .error[data-shown] {
      animation: none;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .error[data-shown] .errorText {
    animation: code-error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .error svg {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    stroke-width: var(--ui-icon-stroke-regular);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    flex-shrink: 0;
  }

  @keyframes code-error-swap {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .error[data-shown] .errorText {
      animation: none;
    }
  }

  /* ---------- Status: the boxes fold into a pill ---------- */

  /* Merging: each box drifts toward the pill's middle as it fades into it. */
  .root[data-phase="verifying"] .box,
  .root[data-phase="success"] .box {
    opacity: 0;
    translate: var(--code-drift, 0) 0;
    filter: blur(2px);
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-exit),
      translate var(--ui-dur-glide) var(--ui-ease-glide),
      filter var(--ui-dur-fast) var(--ui-ease-exit),
      --code-edge var(--ui-dur-instant) var(--ui-ease-color),
      --code-danger var(--ui-dur-fast) var(--ui-ease-color);
  }

  /* A short nudge on a failed code, once the boxes are back. */
  .boxes[data-nudge="0"] {
    animation: code-nudge-a var(--ui-dur-move) var(--ui-ease-pulse);
  }

  .boxes[data-nudge="1"] {
    animation: code-nudge-b var(--ui-dur-move) var(--ui-ease-pulse);
  }

  .boxes[data-nudge-late] {
    animation-delay: var(--ui-dur-glide);
  }

  @keyframes code-nudge-a {
    25% { translate: -4px 0; }
    55% { translate: 3px 0; }
    80% { translate: -1px 0; }
  }

  @keyframes code-nudge-b {
    25% { translate: -4px 0; }
    55% { translate: 3px 0; }
    80% { translate: -1px 0; }
  }

  /* The pill: a quiet fill with no edge, the row's width at rest, the label's
     when folded. Pinned to all four edges with auto margins, so it sits on the
     row's exact center and folds toward it from both sides at once. */
  .pill {
    position: absolute;
    inset: 0;
    margin: auto;
    height: var(--ui-control-md);
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 100%;
    overflow: hidden;
    border-radius: var(--ui-radius-full);
    background: var(--ui-fill);
    color: var(--ui-foreground);
    opacity: 0;
    pointer-events: none;
    /* Opening back up: it widens and, once its words are gone, dissolves into the returning boxes. */
    transition:
      width var(--ui-dur-glide) var(--ui-ease-glide),
      opacity var(--ui-dur-base) var(--ui-ease-color) var(--ui-dur-instant);
  }

  .root[data-phase="verifying"] .pill,
  .root[data-phase="success"] .pill {
    width: var(--code-pill-width, max-content);
    opacity: 1;
    transition:
      width var(--ui-dur-glide) var(--ui-ease-glide),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .pillContent {
    position: relative;
    display: flex;
    flex: none;
    align-items: center;
    gap: var(--ui-space-2);
    /* Even on both sides, so the glyph and words sit on the pill's center. */
    padding-inline: var(--ui-space-4);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
    letter-spacing: var(--ui-tracking-control);
    white-space: nowrap;
    opacity: 0;
    filter: blur(2px);
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      filter var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .root[data-phase="verifying"] .pillContent,
  .root[data-phase="success"] .pillContent {
    opacity: 1;
    filter: none;
    transition:
      opacity var(--ui-dur-base) var(--ui-ease-enter) var(--ui-dur-instant),
      filter var(--ui-dur-base) var(--ui-ease-enter) var(--ui-dur-instant);
  }

  /* Muted while checking; full ink once it's done. No other color. */
  .pillText {
    color: var(--ui-muted);
    transition: color var(--ui-dur-base) var(--ui-ease-color);
  }

  .root[data-phase="success"] .pillText {
    color: var(--ui-foreground);
  }

  /* A ring with a breathing dot while checking; the dot gives way to a drawn check. */
  .glyph {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    flex: none;
    overflow: visible;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke-medium);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .ring {
    opacity: 0.4;
    transition: opacity var(--ui-dur-base) var(--ui-ease-color);
  }

  .root[data-phase="success"] .ring {
    opacity: 1;
  }

  .dot {
    fill: currentColor;
    stroke: none;
    transform-box: fill-box;
    transform-origin: center;
    scale: 0.6;
    transition:
      scale var(--ui-dur-instant) var(--ui-ease-exit),
      opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .root[data-phase="verifying"] .dot {
    animation: code-breathe var(--ui-dur-pulse) var(--ui-ease-pulse) infinite alternate;
  }

  .root[data-phase="success"] .dot {
    scale: 0;
    opacity: 0;
  }

  @keyframes code-breathe {
    from { scale: 0.5; }
    to { scale: 1; }
  }

  .check {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
  }

  .root[data-phase="success"] .check {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw) calc(var(--ui-dur-instant) / 2);
  }

  /* Reduced motion: the same states, by fades alone. */
  @media (prefers-reduced-motion: reduce) {
    .root[data-phase] .box {
      translate: none;
      filter: none;
    }

    .boxes[data-nudge] {
      animation: none;
    }

    /* The pill takes its width while unseen: at once on the way in, after its fade on the way out. */
    .pill {
      transition:
        opacity var(--ui-dur-fast) var(--ui-ease-color),
        width 0s linear var(--ui-dur-fast);
    }

    .root[data-phase="verifying"] .pill,
    .root[data-phase="success"] .pill {
      transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
    }

    .pillContent,
    .root[data-phase] .pillContent {
      filter: none;
    }

    .root[data-phase] .dot {
      animation: none;
    }

    .root[data-phase] .check {
      transition-property: opacity;
    }
  }

  /* Selected for retyping after a failed code: every digit, as one selection, while focus is here. */
  .boxes:focus-within .box[data-replacing] {
    background: color-mix(in oklch, var(--ui-selection), var(--ui-surface));
  }

  .box[data-replacing]::selection {
    background: transparent;
  }
}

"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type KeyboardEvent,
  type MouseEvent,
} from "react";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./code-input.module.css";

type CodeInputProps = {
  /** Visible label for the whole code, e.g. "Verification code". */
  label: string;
  /** Number of boxes, 6 by default. */
  length?: number;
  /** Groups the boxes as the code is read aloud: `3` for 123 456, `[3, 4]` for 123 4567. */
  group?: number | number[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called when a change leaves every box filled: the last digit typed, a paste, or a digit fixed in a full code. */
  onComplete?: (value: string) => void;
  /** Digits only (the default), or letters and digits. */
  characters?: "digits" | "alphanumeric";
  /** Guidance under the boxes, until there's an error to show instead. */
  hint?: string;
  /** Says what went wrong and what to do. Turns every box's edge to danger. */
  error?: string | null;
  /** Submitted with the form under this name. */
  name?: string;
  disabled?: boolean;
  autoFocus?: boolean;
  className?: string;
  /**
   * Where checking the code has got to, set by the app. `verifying` locks the
   * boxes and, once it has lasted 300ms, folds them into one pill; `success`
   * draws a check and says "Verified"; `error` opens the boxes back up.
   */
  status?: CodeInputStatus;
  /** Words for the pill and the default error. */
  labels?: { verifying?: string; success?: string; error?: string };
  /** After `status="error"`: select the first digit so typing writes over the code (default), or clear it. */
  retry?: "select" | "clear";
};

export type CodeInputStatus = "idle" | "verifying" | "success" | "error";

type Phase = "cells" | "verifying" | "success";

const defaultLabels = {
  verifying: "Verifying",
  success: "Verified",
  error: "That code didn’t work. Check it and try again.",
};

/** A one-time code as N boxes. The value is always contiguous: no box past the first empty one takes focus. */
export function CodeInput({
  label,
  length = 6,
  group,
  value: controlled,
  defaultValue = "",
  onValueChange,
  onComplete,
  characters = "digits",
  hint,
  error,
  name,
  disabled,
  autoFocus,
  className,
  status,
  labels: labelsProp,
  retry = "select",
}: CodeInputProps) {
  const id = useId();
  const labelId = `${id}-label`;
  const messageId = `${id}-message`;
  const statusId = `${id}-status`;
  const labels = { ...defaultLabels, ...labelsProp };
  const [uncontrolled, setUncontrolled] = useState(() =>
    clean(defaultValue, characters).slice(0, length),
  );
  const value =
    controlled !== undefined
      ? clean(controlled, characters).slice(0, length)
      : uncontrolled;
  const boxes = useRef<(HTMLInputElement | null)[]>([]);
  const rootRef = useRef<HTMLDivElement>(null);
  const rowRef = useRef<HTMLDivElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const pillRef = useRef<HTMLDivElement>(null);
  const phase = usePhase(status);
  const collapsed = phase !== "cells";
  // A fresh label each time the boxes fold, so it morphs only within one fold.
  const [folds, setFolds] = useState(0);
  const [wasCollapsed, setWasCollapsed] = useState(collapsed);
  const [pillText, setPillText] = useState(
    phase === "success" ? labels.success : labels.verifying,
  );
  if (collapsed !== wasCollapsed) {
    setWasCollapsed(collapsed);
    if (collapsed) setFolds((n) => n + 1);
  }
  const nextPillText =
    phase === "success" ? labels.success : phase === "verifying" ? labels.verifying : pillText;
  if (nextPillText !== pillText) setPillText(nextPillText);
  // Checking or checked: the code can't change under the check.
  const locked = status === "verifying" || status === "success";
  // Applied after the new value renders, so the target box is judged against it.
  const pendingFocus = useRef<number | null>(null);

  const complete = value.length === length;
  const errorText = error || (status === "error" ? labels.error : null);
  const invalid = Boolean(errorText);
  const message = errorText || hint;
  // A line is reserved only when something can show there (even a null error prop).
  const hasMessage = Boolean(hint || error !== undefined || status !== undefined);
  // The last error stays in its slot, faded out, so the slot keeps its height.
  const [lastError, setLastError] = useState(errorText);
  if (errorText && errorText !== lastError) setLastError(errorText);

  // Each time the boxes stand open on an error: a nudge (two names, so it
  // replays) and, once, the retry. Late when the boxes are still opening.
  const failed = status === "error" && !collapsed;
  const [wasFailed, setWasFailed] = useState(failed);
  const [lastPhase, setLastPhase] = useState(phase);
  const [nudge, setNudge] = useState(0);
  const [nudgeLate, setNudgeLate] = useState(false);
  // After a failed code with retry="select": every digit stays, selected, and the next one typed starts over.
  const [replacing, setReplacing] = useState(false);
  const retried = useRef(0);
  // Whether the group holds focus for the boxes while it's a pill.
  const held = useRef(false);
  if (failed !== wasFailed || phase !== lastPhase) {
    setWasFailed(failed);
    setLastPhase(phase);
    if (failed && !wasFailed) {
      setNudge((n) => n + 1);
      setNudgeLate(lastPhase !== "cells");
      if (retry === "clear" && controlled === undefined) setUncontrolled("");
      if (retry === "select") setReplacing(true);
    }
  }

  function focus(index: number) {
    const box = boxes.current[Math.max(0, Math.min(index, length - 1))];
    box?.focus();
    box?.select();
  }

  function commit(next: string, focusIndex?: number) {
    if (locked) return;
    next = next.slice(0, length);
    if (next === value) {
      if (focusIndex !== undefined) focus(Math.min(focusIndex, value.length));
      return;
    }
    pendingFocus.current = focusIndex ?? null;
    if (controlled === undefined) setUncontrolled(next);
    onValueChange?.(next);
    setReplacing(false);
    if (next.length === length) onComplete?.(next);
  }

  useLayoutEffect(() => {
    if (pendingFocus.current === null) return;
    const index = pendingFocus.current;
    pendingFocus.current = null;
    focus(index);
  });

  // The pill's width, and where each box drifts as it merges into it.
  useLayoutEffect(() => {
    const stage = stageRef.current;
    const pill = pillRef.current;
    const row = rowRef.current;
    if (!stage || !pill || !row) return;
    const measure = () => {
      const width = pill.offsetWidth;
      stage.style.setProperty("--code-pill-width", `${width}px`);
      // The pill folds toward the middle of the row.
      const center = stage.clientWidth / 2;
      for (const box of boxes.current) {
        if (!box) continue;
        const drift = (center - (box.offsetLeft + box.offsetWidth / 2)) * 0.6;
        box.style.setProperty("--code-drift", `${Math.round(drift)}px`);
      }
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(pill);
    observer.observe(row);
    return () => observer.disconnect();
  }, [length]);

  /** The box focus may land on: none past the first empty one. */
  const reachable = (index: number) =>
    Math.min(index, value.length, length - 1);

  // Focus follows the shape: the group while it's a pill, the boxes when they return.
  useLayoutEffect(() => {
    const root = rootRef.current;
    const row = rowRef.current;
    if (!root || !row) return;
    const active = document.activeElement;
    if (collapsed) {
      if (row.contains(active)) root.focus();
      held.current = document.activeElement === root;
      row.inert = true;
      return;
    }
    row.inert = false;
    // The group stops being focusable as the boxes return, which drops its focus to the body.
    const hadFocus =
      row.contains(active) ||
      (held.current && (active === root || active === document.body));
    held.current = false;
    if (retried.current === nudge) {
      if (hadFocus && !row.contains(active)) focus(reachable(length - 1));
      return;
    }
    retried.current = nudge;
    // An uncontrolled value was cleared as the failure rendered.
    if (retry === "clear" && controlled !== undefined && value) onValueChange?.("");
    if (hadFocus) focus(0);
    // Runs on a change of shape or a new failure, not on every render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [collapsed, nudge]);

  function handleChange(index: number, event: ChangeEvent<HTMLInputElement>) {
    const input = event.currentTarget;
    const typed = clean(input.value, characters);
    const current = value[index] ?? "";

    if (replacing) {
      // Over a selected code: start again from what was typed, or take a whole new code.
      if (typed.length >= length) fill(0, typed);
      else commit(typed.slice(-1), typed ? 1 : 0);
      return;
    }

    if (typed === "") {
      // Cleared by the platform (some keyboards send no Backspace key).
      commit(value.slice(0, index) + value.slice(index + 1), index);
      return;
    }

    if (typed.length === 2 && current && typed.includes(current)) {
      // The caret was beside the digit rather than over it: keep the one typed.
      const caret = input.selectionStart ?? 2;
      const char = typed[caret - 1] ?? typed.replace(current, "");
      commit(value.slice(0, index) + char + value.slice(index + 1), index + 1);
      return;
    }

    if (typed.length > 1) {
      // A paste, or the one-time code filled in by the platform.
      fill(index, typed);
      return;
    }

    commit(value.slice(0, index) + typed + value.slice(index + 1), index + 1);
  }

  function fill(index: number, chars: string) {
    const next =
      chars.length >= length || replacing ? chars : value.slice(0, index) + chars;
    commit(next, Math.min(next.length, length - 1));
  }

  function handlePaste(index: number, event: ClipboardEvent<HTMLInputElement>) {
    const chars = clean(event.clipboardData.getData("text"), characters);
    event.preventDefault();
    if (chars) fill(index, chars);
  }

  function handleKeyDown(
    index: number,
    event: KeyboardEvent<HTMLInputElement>,
  ) {
    if (replacing && (event.key === "Backspace" || event.key === "Delete")) {
      event.preventDefault();
      commit("", 0);
      return;
    }
    if (
      replacing &&
      event.key.length === 1 &&
      !event.metaKey &&
      !event.ctrlKey &&
      clean(event.key, characters)
    ) {
      event.preventDefault();
      commit(clean(event.key, characters), 1);
      return;
    }
    switch (event.key) {
      case "Backspace": {
        event.preventDefault();
        if (value[index])
          commit(value.slice(0, index) + value.slice(index + 1), index);
        else if (index > 0)
          commit(value.slice(0, index - 1) + value.slice(index), index - 1);
        break;
      }
      case "Delete": {
        event.preventDefault();
        commit(value.slice(0, index) + value.slice(index + 1), index);
        break;
      }
      case "ArrowLeft":
      case "ArrowRight": {
        event.preventDefault();
        const rtl = getComputedStyle(event.currentTarget).direction === "rtl";
        const back = (event.key === "ArrowLeft") !== rtl;
        setReplacing(false);
        focus(back ? Math.max(0, index - 1) : reachable(index + 1));
        break;
      }
      case "Home":
        event.preventDefault();
        setReplacing(false);
        focus(0);
        break;
      case "End":
        event.preventDefault();
        setReplacing(false);
        focus(reachable(length - 1));
        break;
      default:
        // Typing the digit that's already there still moves on.
        if (
          event.key.length === 1 &&
          event.key === value[index] &&
          !event.metaKey &&
          !event.ctrlKey
        ) {
          event.preventDefault();
          focus(index + 1);
        }
    }
  }

  function handleFocus(index: number) {
    const target = reachable(index);
    if (target !== index) focus(target);
    else boxes.current[index]?.select();
  }

  // Stops the browser placing a caret in the box that was hit first.
  function handleMouseDown(index: number, event: MouseEvent<HTMLInputElement>) {
    if (disabled) return;
    event.preventDefault();
    // Clicking a digit means fixing that one, not starting over.
    setReplacing(false);
    focus(reachable(index));
  }

  const groupStarts = groupBoundaries(length, group);

  return (
    <div
      ref={rootRef}
      role="group"
      aria-labelledby={labelId}
      aria-describedby={
        [collapsed && statusId, hasMessage && message && messageId]
          .filter(Boolean)
          .join(" ") || undefined
      }
      aria-busy={status === "verifying" || undefined}
      tabIndex={collapsed ? -1 : undefined}
      className={className ? `${styles.root} ${className}` : styles.root}
      data-complete={complete || undefined}
      data-invalid={invalid ? "" : undefined}
      data-disabled={disabled || undefined}
      data-phase={phase}
    >
      <label
        id={labelId}
        className={styles.label}
        htmlFor={`${id}-${reachable(length - 1)}`}
      >
        {label}
      </label>
      <div ref={stageRef} className={styles.stage}>
      <div
        ref={rowRef}
        className={styles.boxes}
        data-nudge={nudge ? nudge % 2 : undefined}
        data-nudge-late={nudgeLate || undefined}
      >
        {Array.from({ length }, (_, i) => [
          groupStarts.has(i) && (
            <span key={`dot-${i}`} className={styles.separator} aria-hidden="true" />
          ),
          <input
            key={i}
            ref={(node) => {
              boxes.current[i] = node;
            }}
            id={`${id}-${i}`}
            className={styles.box}
            data-filled={value[i] ? "" : undefined}
            data-replacing={(replacing && value[i]) || undefined}
            value={value[i] ?? ""}
            aria-label={`${characters === "digits" ? "Digit" : "Character"} ${i + 1} of ${length}`}
            aria-invalid={invalid || undefined}
            readOnly={locked}
            inputMode={characters === "digits" ? "numeric" : "text"}
            pattern={characters === "digits" ? "[0-9]*" : undefined}
            autoComplete={i === 0 ? "one-time-code" : "off"}
            autoCapitalize={characters === "digits" ? undefined : "characters"}
            autoCorrect="off"
            spellCheck={false}
            enterKeyHint={i === length - 1 ? "done" : "next"}
            disabled={disabled}
            autoFocus={autoFocus && i === 0}
            onChange={(e) => handleChange(i, e)}
            onPaste={(e) => handlePaste(i, e)}
            onKeyDown={(e) => handleKeyDown(i, e)}
            onFocus={() => handleFocus(i)}
            onMouseDown={(e) => handleMouseDown(i, e)}
          />,
        ])}
      </div>
      <div className={styles.pill} aria-hidden="true">
        <div ref={pillRef} className={styles.pillContent}>
          <svg className={styles.glyph} viewBox="0 0 16 16">
            <circle className={styles.ring} cx="8" cy="8" r="6.25" />
            <circle className={styles.dot} cx="8" cy="8" r="2.75" />
            <path
              className={styles.check}
              d="M5.4 8.2l1.8 1.8 3.4-3.8"
              pathLength={1}
            />
          </svg>
          {/* The morph eases its own width; the pill follows it and stays centered. */}
          <TextMorph key={folds} className={styles.pillText}>
            {pillText}
          </TextMorph>
        </div>
      </div>
      </div>
      <span id={statusId} className={styles.srOnly} role="status">
        {phase === "verifying"
          ? labels.verifying
          : phase === "success"
            ? labels.success
            : ""}
      </span>
      {name && <input type="hidden" name={name} value={value} />}
      {hasMessage && (
        <p id={messageId} className={styles.message} aria-live="polite">
          {hint && (
            <span className={styles.hint} data-shown={!invalid || undefined}>
              {hint}
            </span>
          )}
          {lastError && (
            <span
              className={styles.error}
              data-shown={invalid || undefined}
            >
              <svg viewBox="0 0 16 16" aria-hidden="true">
                <circle
                  cx="8"
                  cy="8"
                  r="6.25"
                  fill="none"
                  stroke="currentColor"
                />
                <path
                  d="M8 4.75v3.75"
                  stroke="currentColor"
                  strokeLinecap="round"
                />
                <circle cx="8" cy="11" r="0.9" fill="currentColor" />
              </svg>
              <span key={lastError} className={styles.errorText}>
                {lastError}
              </span>
            </span>
          )}
        </p>
      )}
    </div>
  );
}

/**
 * The shape to show for a status. Fast checks never fold the boxes: the pill
 * appears once `verifying` has lasted 300ms, and then holds 400ms at least.
 */
function usePhase(status: CodeInputStatus | undefined): Phase {
  const target: Phase =
    status === "verifying" ? "verifying" : status === "success" ? "success" : "cells";
  const [phase, setPhase] = useState<Phase>(target === "verifying" ? "cells" : target);
  const since = useRef(0);

  useEffect(() => {
    if (target === phase) return;
    let wait = 0;
    if (target === "verifying" && phase === "cells") wait = 300;
    else if (phase === "verifying")
      wait = Math.max(0, 400 - (performance.now() - since.current));
    const timer = window.setTimeout(() => {
      if (target === "verifying") since.current = performance.now();
      setPhase(target);
    }, wait);
    return () => window.clearTimeout(timer);
  }, [target, phase]);

  return phase;
}

/** Indexes of the boxes that open a new group, after the first. */
function groupBoundaries(length: number, group: number | number[] | undefined) {
  const starts = new Set<number>();
  if (group === undefined) return starts;
  const sizes = typeof group === "number" ? [group] : group;
  if (!sizes.length || sizes.some((n) => !Number.isInteger(n) || n < 1))
    return starts;
  // A single size repeats; a list is used in order and its last size repeats.
  let at = 0;
  for (let g = 0; ; g++) {
    at += sizes[Math.min(g, sizes.length - 1)];
    if (at >= length) break;
    starts.add(at);
  }
  return starts;
}

function clean(text: string, characters: "digits" | "alphanumeric") {
  return characters === "digits"
    ? text.replace(/\D/g, "")
    : text.replace(/[^0-9a-z]/gi, "").toUpperCase();
}

@layer theme, base, components, utilities;

/* Separate registered parts, so focus can move --field-edge instantly while
   --field-danger still eases. */
@property --field-edge {
  syntax: "<color>";
  inherits: false;
  initial-value: transparent;
}

@property --field-danger {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

@layer components {
  .field {
    display: grid;
    gap: var(--ui-space-2);
    font-family: var(--ui-font-sans);
  }

  .label {
    justify-self: start;
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .control {
    --field-height: var(--ui-control-md);
    --reveal-size: var(--ui-control-sm);
    --reveal-inset: calc((var(--field-height) - var(--reveal-size)) / 2);
    position: relative;
    display: grid;
  }

  .field[data-size="lg"] .control {
    --field-height: var(--ui-control-lg);
  }

  .input {
    --field-edge: var(--ui-border-strong);
    --field-edge-width: var(--ui-hairline);
    width: 100%;
    height: var(--ui-control-md);
    /* 14px in, the same as a select's label, so stacked fields line up. */
    padding-inline: calc(var(--reveal-inset) + 10px);
    border: 0;
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: inset 0 0 0 var(--field-edge-width) color-mix(in oklch, var(--field-edge), var(--ui-danger) var(--field-danger));
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    outline: none;
    transition:
      --field-edge var(--ui-dur-instant) var(--ui-ease-color),
      --field-danger var(--ui-dur-fast) var(--ui-ease-color);
  }

  .field[data-size="lg"] .input {
    height: var(--ui-control-lg);
  }

  .input[data-reveal] {
    padding-inline-end: calc(var(--reveal-size) + var(--reveal-inset) * 2);
  }

  /* Edge draws its own reveal button; one is enough. */
  .input::-ms-reveal {
    display: none;
  }

  .reveal {
    --ui-icon-stroke: var(--ui-icon-stroke-regular);
    position: absolute;
    inset-block: var(--reveal-inset);
    inset-inline-end: var(--reveal-inset);
    display: grid;
    place-items: center;
    width: var(--reveal-size);
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-md) - var(--reveal-inset));
    background: transparent;
    color: var(--ui-muted);
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      color var(--ui-dur-instant) var(--ui-ease-color),
      scale var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @media (hover: hover) {
    .reveal:hover:not(:disabled) {
      background: var(--ui-fill);
      color: var(--ui-foreground);
    }
  }

  .reveal:active:not(:disabled) {
    background: var(--ui-fill-strong);
    scale: var(--ui-scale-press);
    transition-duration: var(--ui-dur-press);
  }

  .reveal:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .reveal[aria-pressed="true"] {
    color: var(--ui-foreground);
  }

  .reveal:disabled {
    opacity: 0.5;
    cursor: default;
  }

  @media (pointer: coarse) {
    .reveal::before {
      content: "";
      position: absolute;
      inset: calc(var(--reveal-inset) * -1);
    }
  }

  .input::placeholder {
    color: var(--ui-subtle);
  }

  @media (hover: hover) {
    .input:hover:not(:focus, :disabled, [aria-invalid]) {
      --field-edge: var(--ui-field-focus);
    }
  }

  .input:focus {
    --field-edge: var(--ui-field-focus);
    --field-edge-width: 1px;
    transition:
      --field-edge 0s,
      --field-danger var(--ui-dur-fast) var(--ui-ease-color);
  }

  .input[aria-invalid] {
    --field-danger: 100%;
  }

  .input:disabled {
    opacity: 0.5;
    cursor: default;
    transition: none;
  }

  .message {
    display: grid;
    /* Set --field-message-lines when a longer error can arrive, so it never pushes the page. */
    min-height: calc(var(--field-message-lines, 1) * var(--ui-leading-md));
    margin: 0;
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  .hint,
  .error {
    grid-area: 1 / 1;
    min-width: 0;
    /* Hidden after the fade so it also leaves the accessible description. */
    opacity: 0;
    visibility: hidden;
    transition:
      opacity var(--ui-dur-instant) var(--ui-ease-color),
      visibility 0s linear var(--ui-dur-instant);
  }

  .hint[data-shown],
  .error[data-shown] {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--ui-dur-fast) var(--ui-ease-enter) calc(var(--ui-dur-instant) / 2),
      visibility 0s;
  }

  @starting-style {
    .error[data-shown] {
      opacity: 0;
    }
  }

  .hint {
    color: var(--ui-muted);
  }

  .error {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    color: var(--ui-danger-text);
  }

  .error[data-shown] .errorText {
    animation: error-swap var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .error svg {
    width: var(--ui-icon-sm);
    height: var(--ui-icon-sm);
    stroke-width: var(--ui-icon-stroke-regular);
    margin-top: calc((var(--ui-leading-md) - 14px) / 2);
    flex-shrink: 0;
  }

  @keyframes error-swap {
    from {
      opacity: 0;
    }
  }

  /* iOS zooms the page into any field under 16px. */
  @media (pointer: coarse) {
    .input {
      font-size: var(--ui-text-touch);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .error[data-shown] .errorText {
      animation: none;
    }
    .reveal:active:not(:disabled) {
      scale: none;
    }
  }
}

"use client";

import {
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ComponentProps,
  type FocusEvent,
  type Ref,
} from "react";
import { Icon } from "../icons/icons";
import styles from "./text-field.module.css";

type TextFieldProps = Omit<ComponentProps<"input">, "size"> & {
  label: string;
  /** Guidance shown under the field until there's an error to show instead. */
  hint?: string;
  /** Return a message that says how to fix the value, or null when it's fine. */
  validate?: (value: string) => string | null;
  /** An error from outside, such as the server. Wins over `validate`. */
  error?: string | null;
  size?: "md" | "lg";
};

export function TextField({
  label,
  hint,
  validate,
  error: externalError,
  size = "md",
  className,
  onBlur,
  onChange,
  id,
  type,
  ref,
  ...props
}: TextFieldProps) {
  const fallbackId = useId();
  const inputId = id ?? fallbackId;
  const messageId = `${inputId}-message`;

  // Validate on blur, not mid-typing. Once an error shows, re-check on every
  // keystroke so it clears the moment the value is fixed.
  const [touched, setTouched] = useState(false);
  const [localError, setLocalError] = useState<string | null>(null);
  const error = externalError ?? localError;

  function handleBlur(event: FocusEvent<HTMLInputElement>) {
    setTouched(true);
    setLocalError(validate?.(event.currentTarget.value) ?? null);
    onBlur?.(event);
  }

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    if (touched && localError)
      setLocalError(validate?.(event.currentTarget.value) ?? null);
    onChange?.(event);
  }

  const message = error ?? hint;
  // A line is reserved only when something can show there (even a null error prop).
  const hasMessage = Boolean(hint || validate || externalError !== undefined);

  // The last error stays, faded out, so the slot keeps its height.
  const [lastError, setLastError] = useState(error);
  if (error && error !== lastError) setLastError(error);

  const password = type === "password";
  const [revealed, setRevealed] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const selection = useRef<[number | null, number | null] | null>(null);

  // Switching the type can drop the caret to the start in some browsers.
  useLayoutEffect(() => {
    const input = inputRef.current;
    const saved = selection.current;
    if (!input || !saved) return;
    selection.current = null;
    if (document.activeElement !== input) return;
    const restore = () => {
      if (document.activeElement === input)
        input.setSelectionRange(saved[0], saved[1]);
    };
    restore();
    // Chrome rebuilds the field's editor after the commit and can reset
    // the caret once more, so restore again on the next frame.
    const frame = requestAnimationFrame(restore);
    return () => cancelAnimationFrame(frame);
  }, [revealed]);

  function toggleReveal() {
    const input = inputRef.current;
    if (input) selection.current = [input.selectionStart, input.selectionEnd];
    setRevealed((r) => !r);
  }

  function setRefs(node: HTMLInputElement | null) {
    inputRef.current = node;
    assignRef(ref, node);
  }

  return (
    <div
      className={className ? `${styles.field} ${className}` : styles.field}
      data-size={size}
    >
      <label className={styles.label} htmlFor={inputId}>
        {label}
      </label>
      <div className={styles.control}>
        <input
          ref={setRefs}
          id={inputId}
          type={password && revealed ? "text" : type}
          className={styles.input}
          data-reveal={password || undefined}
          aria-invalid={error ? true : undefined}
          aria-describedby={hasMessage && message ? messageId : undefined}
          spellCheck={password ? false : undefined}
          autoCapitalize={password ? "off" : undefined}
          autoCorrect={password ? "off" : undefined}
          onBlur={handleBlur}
          onChange={handleChange}
          {...props}
        />
        {password && (
          <button
            type="button"
            className={styles.reveal}
            aria-label="Show password"
            aria-pressed={revealed}
            aria-controls={inputId}
            disabled={props.disabled}
            // Keep focus in the input, so the caret and on-screen keyboard stay put.
            onMouseDown={(event) => {
              if (document.activeElement === inputRef.current)
                event.preventDefault();
            }}
            onClick={toggleReveal}
          >
            <Icon name={revealed ? "eye-off" : "eye"} />
          </button>
        )}
      </div>
      {hasMessage && (
        <>
          {/* The hidden one is visibility: hidden, so it's out of the description and live region. */}
          <p id={messageId} className={styles.message} aria-live="polite">
            {hint && (
              <span className={styles.hint} data-shown={!error || undefined}>
                {hint}
              </span>
            )}
            {lastError && (
              <span
                className={styles.error}
                data-shown={error ? true : undefined}
              >
                <svg viewBox="0 0 16 16" aria-hidden="true">
                  <circle
                    cx="8"
                    cy="8"
                    r="6.25"
                    fill="none"
                    stroke="currentColor"
                  />
                  <path
                    d="M8 4.75v3.75"
                    stroke="currentColor"
                    strokeLinecap="round"
                  />
                  <circle cx="8" cy="11" r="0.9" fill="currentColor" />
                </svg>
                {/* A new message fades in over the old one's place. */}
                <span key={lastError} className={styles.errorText}>
                  {lastError}
                </span>
              </span>
            )}
          </p>
        </>
      )}
    </div>
  );
}

function assignRef<T>(ref: Ref<T> | undefined, value: T) {
  if (typeof ref === "function") ref(value);
  else if (ref) ref.current = value;
}

@layer theme, base, components, utilities;

/* "You last signed in with Google.": a muted line under the buttons, the
   same distance below them in either group, so no button changes size and
   no label moves. */
.lastUsed {
  composes: wrap from "../text/text.module.css";
}

.sweep {
  composes: sweep from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  /* The page around the card: centers it, and on a page of its own fills
     the viewport. A container, so the card can go flush on a phone-width
     column whatever the viewport is. */
  .root {
    --sign-in-width: 400px;
    --sign-in-gap: var(--ui-space-5);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    --animated-size-grow: var(--ui-dur-panel);
    --animated-size-shrink: var(--ui-dur-base);
    --animated-size-ease: var(--ui-ease-move);
    container-type: inline-size;
    display: grid;
    place-items: center;
    width: 100%;
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  .root[data-full-page] {
    min-height: 100dvh;
    padding: max(var(--ui-space-6), env(safe-area-inset-top)) var(--ui-space-4)
      max(var(--ui-space-6), env(safe-area-inset-bottom));
    background: var(--ui-canvas);
  }

  /* A surface one step up from the page, with no shadow: it doesn't float. */
  .card {
    display: grid;
    gap: var(--sign-in-gap);
    width: 100%;
    max-width: var(--sign-in-width);
    padding: var(--ui-space-6) var(--ui-space-5) var(--ui-space-5);
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-resting);
  }

  /* On a phone the card is the page: no edge, no inset box, the canvas
     all the way out. */
  @container (max-width: 479px) {
    .card {
      padding-inline: 0;
      border-radius: 0;
      background: none;
      box-shadow: none;
    }
  }

  .brand {
    display: flex;
    justify-content: center;
    min-height: 32px;
    align-items: center;
  }

  .brand > :is(img, svg) {
    height: 32px;
    width: auto;
  }

  .body {
    display: grid;
    gap: var(--sign-in-gap);
  }

  .body[data-enter] {
    animation: sign-in-in var(--ui-dur-panel) var(--ui-ease-enter) 60ms backwards;
  }

  @keyframes sign-in-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }

  .head {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: var(--ui-space-2);
    text-align: center;
  }

  .title {
    margin: 0;
    font-size: var(--ui-text-2xl);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-2xl);
    letter-spacing: var(--ui-tracking-title);
    text-wrap: balance;
  }

  .title:focus {
    outline: none;
  }

  .sub {
    max-width: 34ch;
    margin: 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
    text-wrap: pretty;
  }

  /* A long address breaks anywhere rather than pushing the card wide. */
  .address {
    color: var(--ui-foreground);
    font-weight: var(--ui-weight-medium);
    overflow-wrap: anywhere;
  }

  /* Field, then its button: closer to each other than to anything else. */
  .form {
    display: grid;
    gap: var(--ui-space-3);
  }

  .actions {
    --notice-gap: var(--ui-space-3);
    display: grid;
    gap: var(--notice-gap);
  }

  .wide {
    width: 100%;
  }

  .lastUsed {
    margin: calc(var(--ui-space-2) - var(--notice-gap)) 0 0;
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-align: center;
    text-wrap: balance;
  }

  /* The alert under the button opens its height when it arrives; its gap
     above opens with it, on the same timing, so nothing jumps. */
  .notice {
    transition:
      grid-template-rows var(--ui-dur-base) var(--ui-ease-collapse),
      margin-block-start var(--ui-dur-base) var(--ui-ease-collapse);
  }

  .notice[data-shown] {
    transition-duration: var(--ui-dur-panel);
  }

  .notice:not([data-shown]),
  .notice[data-dismissed] {
    margin-block-start: calc(-1 * var(--notice-gap));
  }

  /* The code boxes sit centered under the centered heading; label and
     message stay with them. */
  .code {
    display: grid;
    justify-items: center;
    /* A server message can run to two lines; the slot is already that tall. */
    --code-message-lines: 2;
  }

  .code > * {
    justify-items: center;
    text-align: center;
  }

  /* "or", between two hairlines. */
  .or {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    gap: var(--ui-space-3);
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .or::before,
  .or::after {
    content: "";
    height: var(--ui-hairline);
    background: var(--ui-border);
  }

  .others {
    --notice-gap: var(--ui-space-2);
    display: grid;
    gap: var(--notice-gap);
  }

  /* A provider's mark, or a neutral letter tile in its place. */
  .mark {
    display: inline-grid;
    place-items: center;
    width: 20px;
    height: 20px;
    flex-shrink: 0;
    overflow: hidden;
    border-radius: calc(var(--ui-radius-sm) / 2);
  }

  .mark[data-monogram] {
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    background: var(--ui-fill);
    color: var(--ui-foreground);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-semibold);
    line-height: 1;
  }

  .mark > :is(img, svg) {
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
  }

  /* Under the code: go back on the start side, resend on the end side.
     They stack on a narrow card. */
  .links {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: var(--ui-space-1) var(--ui-space-2);
    margin-inline: calc(-1 * var(--ui-space-3));
  }

  .links[data-single] {
    justify-content: center;
  }

  @container (max-width: 379px) {
    .links {
      flex-direction: column;
      align-items: center;
    }
  }

  /* Every digit the same width, so the counting label never shifts. */
  .countdown {
    font-variant-numeric: tabular-nums;
  }

  .switch {
    margin: 0;
    text-align: center;
    color: var(--ui-muted);
    font-size: var(--ui-text-md);
    line-height: var(--ui-leading-md);
  }

  /* An inline action that reads as a link. 24px tall at least, for a mouse. */
  .link {
    display: inline-block;
    min-height: 24px;
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-sm) / 2);
    background: none;
    color: var(--ui-foreground);
    font: inherit;
    font-weight: var(--ui-weight-medium);
    text-decoration: underline;
    text-decoration-color: var(--ui-border-strong);
    text-underline-offset: 3px;
    cursor: pointer;
    transition: text-decoration-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    .link:hover {
      text-decoration-color: currentColor;
    }
  }

  .link:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: 2px;
  }

  /* Done: a filled check over the heading. */
  .done {
    display: grid;
    place-items: center;
    width: 40px;
    height: 40px;
    margin-bottom: var(--ui-space-2);
    border-radius: var(--ui-radius-full);
    background: var(--ui-ink);
    color: var(--ui-on-ink);
    animation: sign-in-done var(--ui-dur-bounce) var(--ui-ease-bounce) 80ms backwards;
  }

  .done > svg {
    width: var(--ui-icon-lg);
    height: var(--ui-icon-lg);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
  }

  @keyframes sign-in-done {
    from {
      opacity: 0;
      scale: 0.6;
    }
  }

  /* Terms and privacy: the quietest line on the card. */
  .legal {
    max-width: 36ch;
    justify-self: center;
    text-align: center;
    color: var(--ui-subtle);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    text-wrap: pretty;
  }

  .legal a {
    color: var(--ui-muted);
    text-decoration: underline;
    text-decoration-color: var(--ui-border-strong);
    text-underline-offset: 2px;
  }

  @media (hover: hover) {
    .legal a:hover {
      color: var(--ui-foreground);
    }
  }

  .legal a:focus-visible {
    border-radius: 2px;
    outline: var(--ui-ring-focus);
    outline-offset: 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    .body[data-enter] {
      animation-name: sign-in-fade;
    }
    .done {
      animation-name: sign-in-fade;
    }
  }

  @keyframes sign-in-fade {
    from {
      opacity: 0;
    }
  }
}

"use client";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type FormEvent,
  type ReactNode,
} from "react";
import { Alert } from "../alert/alert";
import { AnimatedSize } from "../animated-size/animated-size";
import { Button } from "../button/button";
import { CodeInput } from "../code-input/code-input";
import { Icon } from "../icons/icons";
import { TextField } from "../text-field/text-field";
import styles from "./sign-in.module.css";

/* ---------- Public types ---------- */

/** What `onSendCode` resolves with. Throwing counts as `{ ok: false, reason: "error" }`. */
export type SendCodeResult =
  | {
      ok: true;
      /** Seconds until the code stops working. Default 600. */
      expiresIn?: number;
      /** Seconds before another code can be asked for. Default 30. */
      resendIn?: number;
    }
  /** The address can't use the product: a blocked domain, a personal address, or invite-only. */
  | { ok: false; reason: "not-allowed"; message?: string }
  /** Too many codes asked for. */
  | { ok: false; reason: "rate-limited"; retryIn: number }
  | { ok: false; reason: "error"; message?: string };

/** What `onVerify` resolves with. Throwing counts as `{ ok: false, reason: "error" }`. */
export type VerifyResult =
  | { ok: true }
  /** `attemptsLeft: 0` means this code is burned and a new one is needed. */
  | { ok: false; reason: "wrong-code"; attemptsLeft?: number }
  | { ok: false; reason: "expired" }
  /** Too many wrong codes: no more tries, and no new code, until `retryIn` seconds pass. */
  | { ok: false; reason: "rate-limited"; retryIn: number }
  | { ok: false; reason: "error"; message?: string };

/**
 * What `onProvider` resolves with. For a redirect, navigate and leave the
 * promise pending: the button stays busy until the page unloads. For a popup,
 * resolve `ok: true` once signed in, or `cancelled` when the person closed it.
 */
export type ProviderResult =
  | { ok: true; email?: string }
  | { ok: false; reason: "cancelled" }
  | { ok: false; reason: "not-allowed"; message?: string }
  | { ok: false; reason: "error"; message?: string };

/** What `onSso` resolves with. Redirect and leave it pending, as with providers. */
export type SsoResult =
  | { ok: true }
  | { ok: false; reason: "not-found" }
  | { ok: false; reason: "error"; message?: string };

export type SignInProvider = {
  id: string;
  /** Shown as "Continue with {name}". */
  name: string;
  /** A 20px mark. Leave it out for a neutral monogram of the first letter. */
  mark?: ReactNode;
};

/** Handed to `onSuccess`: how the person got in. */
export type SignInSuccess =
  | { method: "code"; email: string }
  | { method: "provider"; provider: string; email?: string }
  | { method: "sso"; domain: string };

type Failure<T> = Exclude<T, { ok: true }>;

/** A screen to open on, such as the code step after a reload, or any state in a story or test. */
export type SignInInitialState =
  | {
      step: "email";
      email?: string;
      failure?: Failure<SendCodeResult> | { ok: false; reason: "provider-failed"; provider: string; message?: string };
    }
  | { step: "code"; email: string; expiresIn?: number; resendIn?: number; failure?: Failure<VerifyResult> }
  | { step: "sso"; domain?: string; failure?: Failure<SsoResult> }
  | { step: "done"; success: SignInSuccess };

type SignInProps = {
  /** `sign-up` changes the wording only; the flow is the same. */
  mode?: "sign-in" | "sign-up";
  /** Your product's name, used in the copy: "Sign in to Acme". */
  productName: string;
  /** Your logo or wordmark, centered above the heading. */
  brand?: ReactNode;
  /** Terms and privacy links, at the foot of the card. */
  legal?: ReactNode;
  /** Ask your server to email a code. */
  onSendCode: (email: string) => Promise<SendCodeResult>;
  /** Check the code. Resolve `ok: true` once the session exists. */
  onVerify: (email: string, code: string) => Promise<VerifyResult>;
  /** OAuth buttons, in order. Needs `onProvider`. */
  providers?: SignInProvider[];
  onProvider?: (id: string) => Promise<ProviderResult>;
  /** How this person signed in last time, from your own record (a cookie or
   *  local storage): "email", "sso" or a provider's id. A muted line under
   *  that option's group says "You last signed in with Google.", so a
   *  returning person picks it without thinking. */
  lastUsed?: string;
  /** Shows "Continue with SSO", which asks for the work domain. */
  onSso?: (domain: string) => Promise<SsoResult>;
  /** Called once, after the success screen shows. Navigate from here. */
  onSuccess?: (success: SignInSuccess) => void;
  /** Shows "New to Acme? Create an account" (or the reverse) under the form. */
  onModeChange?: (mode: "sign-in" | "sign-up") => void;
  /** Digits in the code. Default 6. */
  codeLength?: number;
  initialState?: SignInInitialState;
  /** Focus the first field on mount. Steps after the first always move focus. */
  autoFocus?: boolean;
  /** Fill the viewport's height and center in it, for a page of its own. */
  fullPage?: boolean;
  headingLevel?: 1 | 2 | 3;
  className?: string;
};

/* ---------- Internal state ---------- */

type EmailNotice =
  | { kind: "not-allowed"; email: string; message?: string }
  | { kind: "rate-limited"; retryAt: number; retryIn: number }
  | { kind: "error"; message?: string }
  | { kind: "provider-failed"; provider: string; message?: string };

type CodeNotice =
  | { kind: "wrong-code"; attemptsLeft?: number }
  | { kind: "expired" }
  | { kind: "rate-limited"; retryAt: number; retryIn: number }
  | { kind: "error"; message?: string }
  | { kind: "incomplete" };

type View =
  | { step: "email"; notice?: EmailNotice }
  | { step: "code"; email: string; expiresAt: number; expiresIn: number; resendAt: number; resent: number; notice?: CodeNotice }
  | { step: "sso"; notice?: { kind: "not-found"; domain: string } | { kind: "error"; message?: string } }
  | { step: "done"; success: SignInSuccess };

type Busy = null | "send" | "verify" | "resend" | "sso" | `provider:${string}`;

const EXPIRES_IN = 600;
const RESEND_IN = 30;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function initialView(start: SignInInitialState | undefined, providers: SignInProvider[]): View {
  const now = Date.now();
  if (!start) return { step: "email" };
  switch (start.step) {
    case "email": {
      const f = start.failure;
      if (!f) return { step: "email" };
      if (f.reason === "provider-failed")
        return { step: "email", notice: { kind: "provider-failed", provider: providerName(providers, f.provider), message: f.message } };
      return { step: "email", notice: sendNotice(f, start.email ?? "", now) };
    }
    case "code": {
      const expiresIn = start.expiresIn ?? EXPIRES_IN;
      return {
        step: "code",
        email: start.email,
        expiresIn,
        expiresAt: now + expiresIn * 1000,
        resendAt: now + (start.resendIn ?? RESEND_IN) * 1000,
        resent: 0,
        notice: start.failure && verifyNotice(start.failure, now),
      };
    }
    case "sso":
      return { step: "sso", notice: start.failure && ssoNotice(start.failure, start.domain ?? "") };
    case "done":
      return { step: "done", success: start.success };
  }
}

function sendNotice(f: Failure<SendCodeResult>, email: string, now: number): EmailNotice {
  if (f.reason === "not-allowed") return { kind: "not-allowed", email, message: f.message };
  if (f.reason === "rate-limited") return { kind: "rate-limited", retryAt: now + f.retryIn * 1000, retryIn: f.retryIn };
  return { kind: "error", message: f.message };
}

function verifyNotice(f: Failure<VerifyResult>, now: number): CodeNotice {
  if (f.reason === "wrong-code") return { kind: "wrong-code", attemptsLeft: f.attemptsLeft };
  if (f.reason === "expired") return { kind: "expired" };
  if (f.reason === "rate-limited") return { kind: "rate-limited", retryAt: now + f.retryIn * 1000, retryIn: f.retryIn };
  return { kind: "error", message: f.message };
}

function ssoNotice(f: Failure<SsoResult>, domain: string): Extract<View, { step: "sso" }>["notice"] {
  return f.reason === "not-found" ? { kind: "not-found", domain } : { kind: "error", message: f.message };
}

function providerName(providers: SignInProvider[], id: string) {
  return providers.find((p) => p.id === id)?.name ?? id;
}

/** The bare domain in "acme.com", "https://acme.com/" or "mara@acme.com". */
function toDomain(text: string) {
  return text
    .trim()
    .toLowerCase()
    .replace(/^.*@/, "")
    .replace(/^https?:\/\//, "")
    .replace(/\/.*$/, "");
}

/** 0:42, 4:05, or "1 hr 5 min" past the hour. */
function clock(ms: number) {
  const s = Math.max(0, Math.ceil(ms / 1000));
  if (s >= 3600) return `${Math.floor(s / 3600)} hr ${Math.floor((s % 3600) / 60)} min`;
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

/** For screen readers, said once: "about 3 minutes". */
function roughly(seconds: number) {
  if (seconds < 60) return `${Math.max(1, Math.round(seconds))} seconds`;
  const min = Math.round(seconds / 60);
  if (min < 60) return `about ${min} minute${min === 1 ? "" : "s"}`;
  const hr = Math.round(min / 60);
  return `about ${hr} hour${hr === 1 ? "" : "s"}`;
}

/** Ticks after mount only, so the server and the first client render agree. */
function useNow(on: boolean) {
  const [now, setNow] = useState<number | null>(null);
  useEffect(() => {
    if (!on) return;
    const tick = () => setNow(Date.now());
    const first = window.setTimeout(tick, 0);
    const id = window.setInterval(tick, 500);
    return () => {
      window.clearTimeout(first);
      window.clearInterval(id);
    };
  }, [on]);
  return now;
}

/* ---------- Component ---------- */

/** The sign-in or sign-up screen: work email, then a one-time code, with optional OAuth providers and SSO. */
export function SignIn({
  mode = "sign-in",
  productName,
  brand,
  legal,
  onSendCode,
  onVerify,
  providers = [],
  onProvider,
  onSso,
  lastUsed,
  onSuccess,
  onModeChange,
  codeLength = 6,
  initialState,
  autoFocus = false,
  fullPage = false,
  headingLevel = 1,
  className,
}: SignInProps) {
  const H = `h${headingLevel}` as "h1";
  const titleId = useId();
  const [view, setView] = useState<View>(() => initialView(initialState, providers));
  const [email, setEmail] = useState(() =>
    initialState?.step === "email" || initialState?.step === "code" ? (initialState.email ?? "") : "",
  );
  const [emailError, setEmailError] = useState<string | null>(null);
  const [domain, setDomain] = useState(() => (initialState?.step === "sso" ? (initialState.domain ?? "") : ""));
  const [domainError, setDomainError] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState<Busy>(null);
  const [announce, setAnnounce] = useState("");

  const signUp = mode === "sign-up";
  const showProviders = providers.length > 0 && Boolean(onProvider);
  const lastUsedId = useId();
  // The provider or SSO option signed in with last, named under the buttons.
  const lastOther =
    lastUsed === "sso" && onSso
      ? "SSO"
      : showProviders
        ? providers.find((p) => p.id === lastUsed)?.name
        : undefined;

  // Bumped whenever the person leaves a step, so a late answer for it is dropped.
  const epoch = useRef(0);
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const headingRef = useRef<HTMLHeadingElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const domainRef = useRef<HTMLInputElement>(null);
  const codeRef = useRef<HTMLDivElement>(null);

  // Ticks only while something on screen counts down.
  const counting =
    (view.step === "email" && view.notice?.kind === "rate-limited") || view.step === "code";
  const now = useNow(counting);

  /* Focus follows the step: into its first field, or onto the heading once done. */
  const firstStep = useRef(true);
  useLayoutEffect(() => {
    const first = firstStep.current;
    firstStep.current = false;
    if (first && !autoFocus) return;
    if (view.step === "email") emailRef.current?.focus();
    else if (view.step === "code") codeRef.current?.querySelector("input")?.focus();
    else if (view.step === "sso") domainRef.current?.focus();
    else headingRef.current?.focus();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- only a change of step moves focus
  }, [view.step]);

  // Bumped to send focus back to the code's first empty box, after a wrong code or a resend.
  const [codeFocus, setCodeFocus] = useState(0);
  useLayoutEffect(() => {
    if (codeFocus) codeRef.current?.querySelector("input")?.focus();
  }, [codeFocus]);

  // Steps after the first fade up into place.
  const [moves, setMoves] = useState(0);

  /* Hand off once, after the success screen has painted. */
  const handedOff = useRef(false);
  useEffect(() => {
    if (view.step !== "done" || handedOff.current) return;
    handedOff.current = true;
    onSuccess?.(view.success);
  }, [view, onSuccess]);

  /** Runs one request; drops its answer if the person moved on or the block unmounted. */
  async function request<T>(key: Exclude<Busy, null>, fn: () => Promise<T>): Promise<T | { ok: false; reason: "error"; message?: string } | null> {
    const at = epoch.current;
    setBusy(key);
    let result: T | { ok: false; reason: "error"; message?: string };
    try {
      result = await fn();
    } catch {
      result = { ok: false, reason: "error" };
    }
    if (!mounted.current || at !== epoch.current) return null;
    setBusy(null);
    return result;
  }

  function leave(next: View) {
    epoch.current++;
    setBusy(null);
    setView(next);
    setMoves((n) => n + 1);
  }

  /* ----- Email ----- */

  async function sendCode(event?: FormEvent) {
    event?.preventDefault();
    if (busy) return;
    const address = email.trim();
    if (!EMAIL.test(address)) {
      setEmailError(address ? "Enter a full email, like name@company.com." : "Enter your work email.");
      emailRef.current?.focus();
      return;
    }
    if (view.step === "email" && view.notice?.kind === "rate-limited" && now !== null && now < view.notice.retryAt) return;
    setEmailError(null);
    const result = await request("send", () => onSendCode(address));
    if (!result) return;
    const t = Date.now();
    if (result.ok) {
      const expiresIn = result.expiresIn ?? EXPIRES_IN;
      setCode("");
      leave({
        step: "code",
        email: address,
        expiresIn,
        expiresAt: t + expiresIn * 1000,
        resendAt: t + (result.resendIn ?? RESEND_IN) * 1000,
        resent: 0,
      });
      setAnnounce(`We sent a ${codeLength}-digit code to ${address}.`);
    } else {
      setView({ step: "email", notice: sendNotice(result, address, t) });
    }
  }

  async function provider(p: SignInProvider) {
    if (busy || !onProvider) return;
    const result = await request(`provider:${p.id}`, () => onProvider(p.id));
    if (!result) return;
    if (result.ok) leave({ step: "done", success: { method: "provider", provider: p.id, email: result.email } });
    else if (result.reason === "cancelled") setView({ step: "email" });
    else if (result.reason === "not-allowed")
      setView({ step: "email", notice: { kind: "not-allowed", email: "", message: result.message } });
    else setView({ step: "email", notice: { kind: "provider-failed", provider: p.name, message: result.message } });
  }

  /* ----- Code ----- */

  const codeView = view.step === "code" ? view : null;
  const expired =
    codeView !== null && (codeView.notice?.kind === "expired" || (now !== null && now >= codeView.expiresAt));
  const locked =
    codeView?.notice?.kind === "rate-limited" && (now === null || now < codeView.notice.retryAt);
  const burned = codeView?.notice?.kind === "wrong-code" && codeView.notice.attemptsLeft === 0;
  const needsNewCode = expired || burned || codeView?.notice?.kind === "rate-limited";

  async function verify(value: string) {
    if (busy || !codeView || needsNewCode) return;
    if (value.length < codeLength) {
      setView({ ...codeView, notice: { kind: "incomplete" } });
      setCodeFocus((n) => n + 1);
      return;
    }
    const at = codeView;
    const result = await request("verify", () => onVerify(at.email, value));
    if (!result) return;
    if (result.ok) {
      leave({ step: "done", success: { method: "code", email: at.email } });
      return;
    }
    const notice = verifyNotice(result, Date.now());
    setView({ ...at, notice });
    // A wrong code is cleared so the next one can be typed straight in.
    if (notice.kind === "wrong-code" || notice.kind === "error") {
      setCode("");
      setCodeFocus((n) => n + 1);
    }
  }

  async function resend() {
    if (busy || !codeView) return;
    const at = codeView;
    const result = await request("resend", () => onSendCode(at.email));
    if (!result) return;
    const t = Date.now();
    if (result.ok) {
      const expiresIn = result.expiresIn ?? EXPIRES_IN;
      setCode("");
      setView({
        ...at,
        expiresIn,
        expiresAt: t + expiresIn * 1000,
        resendAt: t + (result.resendIn ?? RESEND_IN) * 1000,
        resent: at.resent + 1,
        notice: undefined,
      });
      setCodeFocus((n) => n + 1);
    } else if (result.reason === "rate-limited") {
      setView({ ...at, notice: { kind: "rate-limited", retryAt: t + result.retryIn * 1000, retryIn: result.retryIn } });
    } else {
      setView({ ...at, notice: { kind: "error", message: result.message ?? "Couldn’t send a new code. Check your connection and try again." } });
    }
  }

  function changeCode(next: string) {
    if (busy === "verify") return;
    setCode(next);
    // Typing clears a complaint about the last code, not one about the code itself.
    const kind = codeView?.notice?.kind;
    if (codeView && (kind === "wrong-code" || kind === "error" || kind === "incomplete") && !burned)
      setView({ ...codeView, notice: undefined });
  }

  function differentEmail() {
    leave({ step: "email" });
    setCode("");
  }

  /* ----- SSO ----- */

  function openSso() {
    if (busy) return;
    if (!domain && EMAIL.test(email.trim())) setDomain(toDomain(email));
    leave({ step: "sso" });
  }

  async function sso(event: FormEvent) {
    event.preventDefault();
    if (busy || !onSso) return;
    const d = toDomain(domain);
    if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(d)) {
      setDomainError(d ? "Enter a domain, like company.com." : "Enter your work email or company domain.");
      domainRef.current?.focus();
      return;
    }
    setDomainError(null);
    const result = await request("sso", () => onSso(d));
    if (!result) return;
    if (result.ok) leave({ step: "done", success: { method: "sso", domain: d } });
    else setView({ step: "sso", notice: ssoNotice(result, d) });
  }

  /* ---------- Render ---------- */

  let body: ReactNode;

  if (view.step === "email") {
    const notice = view.notice;
    const limited = notice?.kind === "rate-limited" && (now === null || now < notice.retryAt);
    const alert = notice && !(notice.kind === "rate-limited" && !limited) ? emailAlert(notice, productName, signUp, now) : null;
    // A provider's failure shows under the providers, next to the button that was pressed.
    const fromProvider = notice?.kind === "provider-failed" || (notice?.kind === "not-allowed" && !notice.email);
    body = (
      <div key="email" className={styles.body} data-enter={moves ? "" : undefined}>
        <div className={styles.head}>
          <H id={titleId} ref={headingRef} tabIndex={-1} className={styles.title}>
            {signUp ? `Create your ${productName} account` : `Sign in to ${productName}`}
          </H>
          <p className={styles.sub}>
            {signUp
              ? "Start with your work email. We’ll send you a code, so there’s no password to remember."
              : "Use your work email and we’ll send you a code. No password needed."}
          </p>
        </div>

        <form className={styles.form} onSubmit={sendCode} noValidate>
          <TextField
            ref={emailRef}
            label="Work email"
            type="email"
            name="email"
            autoComplete="email"
            inputMode="email"
            autoCapitalize="none"
            spellCheck={false}
            placeholder="name@company.com"
            value={email}
            error={emailError}
            onChange={(e) => {
              setEmail(e.currentTarget.value);
              if (emailError) setEmailError(null);
              if (view.notice && view.notice.kind !== "rate-limited") setView({ step: "email" });
            }}
          />
          <div className={styles.actions}>
            <Button
              type="submit"
              className={styles.wide}
              aria-describedby={lastUsed === "email" ? lastUsedId : undefined}
              busy={busy === "send"} busyLabel="Sending code…" disabled={limited}>
              Continue with email
            </Button>
            {lastUsed === "email" && <LastUsed id={lastUsedId} name="email" />}
            <Alert
              className={styles.notice}
              open={Boolean(alert) && !fromProvider}
              arrive="expand"
              tone={alert?.tone ?? "error"}
              title={alert?.title ?? ""}
            >
              {alert?.body}
            </Alert>
          </div>
        </form>

        {(showProviders || onSso) && (
          <>
            <div className={styles.or} role="separator">
              <span>or</span>
            </div>
            <div className={styles.others}>
              {showProviders &&
                providers.map((p) => (
                  <Button
                    key={p.id}
                    variant="secondary"
                    className={styles.wide}
                    busy={busy === `provider:${p.id}`}
                    busyLabel={
                      <>
                        <Mark provider={p} />
                        Opening {p.name}…
                      </>
                    }
                    aria-describedby={lastUsed === p.id ? lastUsedId : undefined}
                    onClick={() => provider(p)}
                  >
                    <Mark provider={p} />
                    Continue with {p.name}
                  </Button>
                ))}
              {onSso && (
                <Button
                  variant="secondary"
                  className={styles.wide}
                  aria-describedby={lastUsed === "sso" ? lastUsedId : undefined}
                  onClick={openSso}
                >
                  <span className={styles.mark} aria-hidden="true">
                    <SsoGlyph />
                  </span>
                  Continue with SSO
                </Button>
              )}
              {lastOther && <LastUsed id={lastUsedId} name={lastOther} />}
              <Alert
                className={styles.notice}
                open={Boolean(alert) && fromProvider}
                arrive="expand"
                tone={alert?.tone ?? "error"}
                title={alert?.title ?? ""}
              >
                {alert?.body}
              </Alert>
            </div>
          </>
        )}

        {onModeChange && (
          <p className={styles.switch}>
            {signUp ? "Already have an account? " : `New to ${productName}? `}
            <button type="button" className={styles.link} onClick={() => onModeChange(signUp ? "sign-in" : "sign-up")}>
              {signUp ? "Sign in" : "Create an account"}
            </button>
          </p>
        )}
      </div>
    );
  } else if (view.step === "code") {
    const notice = view.notice;
    const canResend = needsNewCode ? !locked : now !== null && now >= view.resendAt;
    const waitMs = locked && notice?.kind === "rate-limited" ? notice.retryAt - (now ?? 0) : view.resendAt - (now ?? 0);
    body = (
      <div key="code" className={styles.body} data-enter={moves ? "" : undefined}>
        <div className={styles.head}>
          <H id={titleId} ref={headingRef} tabIndex={-1} className={styles.title}>
            Check your email
          </H>
          <p className={styles.sub}>
            Enter the {codeLength}-digit code we sent to <strong className={styles.address}>{view.email}</strong>
          </p>
        </div>

        <form
          className={styles.form}
          onSubmit={(e) => {
            e.preventDefault();
            if (needsNewCode) resend();
            else verify(code);
          }}
        >
          <div ref={codeRef} className={styles.code}>
            <CodeInput
              label="Verification code"
              length={codeLength}
              value={code}
              onValueChange={changeCode}
              onComplete={verify}
              disabled={locked}
              hint={
                view.resent
                  ? `We sent a new code. Earlier codes no longer work.`
                  : `It expires in ${roughly(view.expiresIn).replace("about ", "")}. Check spam if it isn’t there.`
              }
              error={codeError(notice, expired, codeLength)}
            />
          </div>
          <div className={styles.actions}>
            {needsNewCode ? (
              <Button
                type="submit"
                className={styles.wide}
                busy={busy === "resend"}
                busyLabel="Sending…"
                disabled={!canResend}
              >
                {locked ? <Countdown label="Send a new code in" ms={waitMs} known={now !== null} /> : "Send a new code"}
              </Button>
            ) : (
              <Button type="submit" className={styles.wide} busy={busy === "verify"} busyLabel="Checking code…">
                {signUp ? "Create account" : "Sign in"}
              </Button>
            )}
          </div>
        </form>

        <div className={styles.links}>
          <Button variant="ghost" onClick={differentEmail}>
            <Icon name="arrow-left" />
            Use a different email
          </Button>
          {!needsNewCode && (
            <Button
              variant="ghost"
              disabled={!canResend}
              busy={busy === "resend"}
              busyLabel="Sending…"
              onClick={resend}
            >
              {canResend ? "Resend code" : <Countdown label="Resend in" ms={waitMs} known={now !== null} />}
            </Button>
          )}
        </div>
      </div>
    );
  } else if (view.step === "sso") {
    const notice = view.notice;
    body = (
      <div key="sso" className={styles.body} data-enter={moves ? "" : undefined}>
        <div className={styles.head}>
          <H id={titleId} ref={headingRef} tabIndex={-1} className={styles.title}>
            {signUp ? "Sign up with SSO" : "Sign in with SSO"}
          </H>
          <p className={styles.sub}>Enter your work email or your company’s domain. We’ll take you to its sign-in page.</p>
        </div>
        <form className={styles.form} onSubmit={sso} noValidate>
          <TextField
            ref={domainRef}
            label="Work email or domain"
            name="domain"
            autoComplete="email"
            autoCapitalize="none"
            spellCheck={false}
            placeholder="company.com"
            value={domain}
            error={
              domainError ??
              (notice?.kind === "not-found"
                ? `${notice.domain} hasn’t set up SSO with ${productName}. Check the spelling, or go back and use your email.`
                : notice?.kind === "error"
                  ? (notice.message ?? "Couldn’t reach your company’s sign-in page. Try again in a moment.")
                  : null)
            }
            onChange={(e) => {
              setDomain(e.currentTarget.value);
              if (domainError) setDomainError(null);
              if (notice) setView({ step: "sso" });
            }}
          />
          <div className={styles.actions}>
            <Button type="submit" className={styles.wide} busy={busy === "sso"} busyLabel="Finding your company…">
              Continue
            </Button>
          </div>
        </form>
        <div className={styles.links} data-single>
          <Button variant="ghost" onClick={() => leave({ step: "email" })}>
            <Icon name="arrow-left" />
            Other ways to {signUp ? "sign up" : "sign in"}
          </Button>
        </div>
      </div>
    );
  } else {
    const s = view.success;
    body = (
      <div key="done" className={styles.body} data-enter={moves ? "" : undefined}>
        <div className={styles.head}>
          <span className={styles.done} aria-hidden="true">
            <Icon name="check" />
          </span>
          <H id={titleId} ref={headingRef} tabIndex={-1} className={styles.title}>
            {signUp ? "Your account is ready" : "You’re signed in"}
          </H>
          {(s.method === "code" || (s.method === "provider" && s.email)) && (
            <p className={styles.sub}>
              <strong className={styles.address}>{s.email}</strong>
            </p>
          )}
          <p className={`${styles.sub} ${styles.sweep}`}>Opening {productName}…</p>
        </div>
      </div>
    );
  }

  return (
    <section
      className={[styles.root, className].filter(Boolean).join(" ")}
      data-full-page={fullPage || undefined}
      data-step={view.step}
      aria-labelledby={titleId}
      aria-busy={busy ? true : undefined}
    >
      <div className={styles.card}>
        {brand && <div className={styles.brand}>{brand}</div>}
        <AnimatedSize>{body}</AnimatedSize>
        {legal && <div className={styles.legal}>{legal}</div>}
      </div>
      <span role="status" className={styles.srOnly}>
        {view.step === "done" ? (signUp ? "Account created." : "Signed in.") : announce}
      </span>
    </section>
  );
}

function codeError(notice: CodeNotice | undefined, expired: boolean, length: number) {
  if (notice?.kind === "rate-limited")
    return `Too many tries. You can ask for a new code in ${roughly(notice.retryIn)}.`;
  if (notice?.kind === "wrong-code") {
    const n = notice.attemptsLeft;
    if (n === 0) return "That code didn’t match, and it can’t be tried again. Send a new code.";
    if (n === undefined) return "That code didn’t match. Check the latest email and try again.";
    return `That code didn’t match. ${n} ${n === 1 ? "try" : "tries"} left.`;
  }
  if (expired) return "This code has expired. Send a new one to keep going.";
  if (notice?.kind === "incomplete") return `Enter all ${length} digits.`;
  if (notice?.kind === "error") return notice.message ?? "Couldn’t check the code. Check your connection and try again.";
  return null;
}

function emailAlert(notice: EmailNotice, product: string, signUp: boolean, now: number | null) {
  switch (notice.kind) {
    case "not-allowed":
      return {
        tone: "warning" as const,
        title: notice.email ? `${notice.email} can’t ${signUp ? "sign up" : "sign in"} here` : `That account can’t ${signUp ? "sign up" : "sign in"} here`,
        body:
          notice.message ??
          (signUp
            ? `${product} is invite-only for now. Ask someone on your team to invite you, then use the email the invite went to.`
            : `There’s no ${product} account for it. Check for typos, or ask your workspace admin to invite you.`),
      };
    case "rate-limited":
      return {
        tone: "warning" as const,
        title: "Too many codes asked for",
        body: (
          <>
            For your security, wait{" "}
            <Countdown ms={notice.retryAt - (now ?? 0)} known={now !== null} spoken={roughly(notice.retryIn)} />{" "}
            before asking for another.
          </>
        ),
      };
    case "provider-failed":
      return {
        tone: "error" as const,
        title: `Signing in with ${notice.provider} didn’t finish`,
        body: notice.message ?? `${notice.provider} didn’t send you back to ${product}. Try again, or continue with your email.`,
      };
    case "error":
      return {
        tone: "error" as const,
        title: "Couldn’t send the code",
        body: notice.message ?? `${product} didn’t answer. Check your connection and try again.`,
      };
  }
}

/** A ticking m:ss, shown to the eye; screen readers get `spoken` once instead of every second. */
function Countdown({ label, ms, known, spoken }: { label?: string; ms: number; known: boolean; spoken?: string }) {
  return (
    <span className={styles.countdown}>
      {label && `${label} `}
      <span aria-hidden={spoken ? true : undefined}>{known ? clock(ms) : "–:––"}</span>
      {spoken && <span className={styles.srOnly}>{spoken}</span>}
    </span>
  );
}

/** A quiet line under the buttons, so every button keeps the same size and
 *  label position. The button it names points at it with aria-describedby:
 *  "Continue with Google, button, You last signed in with Google." */
function LastUsed({ id, name }: { id: string; name: string }) {
  return (
    <p id={id} className={styles.lastUsed}>
      You last signed in with {name}.
    </p>
  );
}

/** A neutral letter tile when no mark is passed. provider-marks.tsx has Google, GitHub and Microsoft. */
function Mark({ provider }: { provider: SignInProvider }) {
  return (
    <span className={styles.mark} data-monogram={provider.mark ? undefined : ""} aria-hidden="true">
      {provider.mark ?? provider.name.trim().charAt(0).toLocaleUpperCase()}
    </span>
  );
}

function SsoGlyph() {
  return (
